      "description": "Ramp traffic to 50% through the mesh using an updated VirtualService",
      "action": "apply",
      "target": "VirtualService",
      "risk_class": "high",
      "rollback": {
        "trigger": "ramp operation fails",
        "action": "rollback to 1% routing",
        "safety_guard": "verify traffic routed to 1%"
      },
      "verification": {
        "what": "traffic routing percentage",
        "how": "check VirtualService configuration",
        "expected": "50%"
      },
      "preconditions": [
        {
          "description": "Metrics stable for 1%",
          "fact": "metrics_observed_1%",
