      "target": "metrics",
      "risk_class": "medium",
      "preconditions": [
        {
          "description": "Traffic ramped to 50%",
          "fact": "traffic_ramped_50%",
          "established_by": "ramp-traffic-50%"
        }
      ]
    },
    {
      "id": "rollback-if-necessary",
      "description": "Auto-rollback if metrics exceed defined thresholds",
      "action": "check_metrics",
      "target": "metrics",
      "risk_class": "critical",
      "rollback": {
        "trigger": "p99 latency > 200ms or error rate > baseline",
        "action": "remove label and patch deployments",
        "safety_guard": "ensure deployments are running"
      },
      "verification": {
        "what": "system status after rollback",
        "how": "check deployments and namespace",
        "expected": "no mesh traffic"
      },
      "preconditions": [
        {
          "description": "Observed metrics for 50%",
          "fact": "metrics_observed_50%",
          "established_by": "observe-traffic-50%"
        }
      ]
    },
    {
      "id": "route-100%",
      "description": "Route 100% of traffic through the mesh once verified",
      "action": "apply",
      "target": "VirtualService",
      "risk_class": "high",
      "rollback": {
        "trigger": "routing fails",
        "action": "remove VirtualService",
        "safety_guard": "confirm no traffic routed"
      },
      "verification": {
        "what": "traffic routing percentage",
        "how": "check VirtualService configuration",
        "expected": "100%"
      },
      "preconditions": [
        {
          "description": "No rollback triggered",
          "fact": "rollback_not_needed",
          "established_by": "rollback-if-necessary"
        }
      ]
    },
    {
      "id": "decommission-legacy",
      "description": "Decommission the legacy sidecar-free Deployments",
      "action": "delete",
      "target": "Deployments",
      "risk_class": "medium",
      "preconditions": [
        {
          "description": "100% traffic successfully routed",
          "fact": "traffic_routed_100%",
          "established_by": "route-100%"
        }
      ]
    }
  ],
  "dependencies": [
    {
      "from_task": "label-namespace",
      "to_task": "route-traffic-1%",
      "kind": "hard"
    },
    {
      "from_task": "route-traffic-1%",
      "to_task": "observe-traffic-1%",
      "kind": "hard"
    },
    {
      "from_task": "observe-traffic-1%",
      "to_task": "ramp-traffic-50%",
      "kind": "hard"
    },
    {
      "from_task": "ramp-traffic-50%",
